#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# ask_path VAR "Prompt" reads a file path into $VAR until one exists. Accepts a file dragged
# into the terminal, which macOS may quote, escape or follow with a space.
ask_path() {
  local key="$1" prompt="$2" path
  while :; do
    read -e -r -p "  $BOLD$prompt$RESET " path || return 1
    path="${path% }"; path="${path%\"}"; path="${path#\"}"; path="${path//\\ / }"
    [[ -f "$path" ]] && break
    warn "No file at $path. Try again."
  done
  printf -v "$key" '%s' "$path"
}

run_wizard() {

TOTAL_STAGES=7

# Everything this wizard makes lives outside the repo, readable only by you.
WORK="${NIBBLE_RELEASE_DIR:-$HOME/.nibble-release}"
ENV_FILE="$WORK/values.env"
CONF="crates/nibble-app/tauri.conf.json"
cd "$(git rev-parse --show-toplevel)"
(umask 077 && mkdir -p "$WORK")

banner "nibble: release signing secrets"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check the tools"
say "This sets up everything the release workflow (.github/workflows/release.yml) needs:"
step "a Developer ID Application certificate, so macOS trusts the app"
step "an App Store Connect API key, so CI can notarize it"
step "an updater key, so installed copies accept new versions"
say ""
say "Working files go to $WORK, never into the repo."
for tool in gh openssl pnpm node git; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is missing. Install it and re-run."; exit 1; }
done
gh auth status >/dev/null 2>&1 || { warn "gh is not signed in. Run: gh auth login"; exit 1; }
say "Secrets will be set on: $(gh repo view --json nameWithOwner --jq .nameWithOwner)"
confirm "Is your Apple Developer Program membership active?" || {
  note "Enroll at https://developer.apple.com/programs/enroll/ and re-run once Apple approves you."
  exit 0
}

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Developer ID Application certificate"
if [[ -f "$WORK/developer-id.cer" ]]; then
  note "Found $WORK/developer-id.cer from an earlier run; keeping it."
  pause
else
  if [[ ! -f "$WORK/developer-id.key" ]]; then
    (umask 077 && openssl req -new -newkey rsa:2048 -nodes \
      -keyout "$WORK/developer-id.key" -out "$WORK/developer-id.csr" \
      -subj "/CN=nibble Developer ID" 2>/dev/null)
  fi
  say "Made a certificate signing request: $WORK/developer-id.csr"
  open_url "https://developer.apple.com/account/resources/certificates/add"
  step "Choose 'Developer ID Application', then Continue."
  step "Profile type: 'G2 Sub-CA'. Upload $WORK/developer-id.csr, then Continue."
  step "Download the certificate (developer_id_application.cer)."
  note "If the page has changed, look for the Developer ID Application certificate."
  ask_path DOWNLOADED_CER "Path to the downloaded .cer (drag the file here):"
  cp "$DOWNLOADED_CER" "$WORK/developer-id.cer"
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Package the certificate for CI"
openssl x509 -inform DER -in "$WORK/developer-id.cer" -out "$WORK/developer-id.pem"
IDENTITY=$(openssl x509 -in "$WORK/developer-id.pem" -noout -subject -nameopt multiline \
  | sed -n 's/^ *commonName *= *//p')
[[ "$IDENTITY" == "Developer ID Application:"* ]] || {
  warn "That certificate is '$IDENTITY', not a Developer ID Application one."
  warn "Delete $WORK/developer-id.cer and re-run."
  exit 1
}
say "Signing identity: $IDENTITY"
write_env APPLE_SIGNING_IDENTITY "$IDENTITY"
P12_PASSWORD=$(_existing APPLE_CERTIFICATE_PASSWORD || openssl rand -base64 24)
write_env APPLE_CERTIFICATE_PASSWORD "$P12_PASSWORD"
# 3DES and SHA-1 MAC: the .p12 format macOS's `security import` reads.
(umask 077 && openssl pkcs12 -export \
  -inkey "$WORK/developer-id.key" -in "$WORK/developer-id.pem" \
  -keypbe PBE-SHA1-3DES -certpbe PBE-SHA1-3DES -macalg sha1 \
  -passout "pass:$P12_PASSWORD" -out "$WORK/developer-id.p12")
say "Packaged $WORK/developer-id.p12 with a generated password."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "App Store Connect API key (notarization)"
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "Open 'Team Keys'. The first time, click 'Request Access' and accept."
step "Click Generate API Key (or +). Name: nibble notarization. Access: Developer."
step "Download the key (AuthKey_XXXXXXXXXX.p8). Apple lets you download it only once."
ask APPLE_API_ISSUER "Issuer ID (shown above the keys table):"
write_env APPLE_API_ISSUER "$APPLE_API_ISSUER"
ask APPLE_API_KEY "Key ID (the key's row in the table):"
write_env APPLE_API_KEY "$APPLE_API_KEY"
if [[ -f "$WORK/AuthKey.p8" ]]; then
  note "Found $WORK/AuthKey.p8 from an earlier run; keeping it."
else
  ask_path P8_FILE "Path to the downloaded .p8 (drag the file here):"
  (umask 077 && cp "$P8_FILE" "$WORK/AuthKey.p8")
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Updater signing key"
if [[ -f "$WORK/updater.key" ]]; then
  note "Found $WORK/updater.key from an earlier run; keeping it."
  note "Never replace it once a release is out: installed copies trust only this key."
  UPDATER_PASSWORD=$(_existing TAURI_SIGNING_PRIVATE_KEY_PASSWORD || true)
  [[ -n "$UPDATER_PASSWORD" ]] || ask_secret UPDATER_PASSWORD "Its password:"
else
  UPDATER_PASSWORD=$(openssl rand -base64 24)
  pnpm exec tauri signer generate --ci -p "$UPDATER_PASSWORD" -w "$WORK/updater.key" >/dev/null
  chmod 600 "$WORK/updater.key"
  say "Generated $WORK/updater.key with a generated password."
fi
write_env TAURI_SIGNING_PRIVATE_KEY_PASSWORD "$UPDATER_PASSWORD"
PUBKEY=$(cat "$WORK/updater.key.pub")
PUBKEY="$PUBKEY" node -e '
  const fs = require("fs");
  const path = process.argv[1];
  const conf = JSON.parse(fs.readFileSync(path, "utf8"));
  conf.plugins.updater.pubkey = process.env.PUBKEY;
  fs.writeFileSync(path, JSON.stringify(conf, null, 2) + "\n");
' "$CONF"
pnpm exec prettier --write "$CONF" >/dev/null
printf '  %s✓ wrote%s the public key → %s\n' "$GREEN" "$RESET" "$CONF"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Back up to your password manager"
say "Make one entry, e.g. 'nibble release signing', with these files and values."
say "Losing the updater key means installed copies can never update themselves again."
step "File: $WORK/updater.key"
step "File: $WORK/developer-id.p12"
step "File: $WORK/AuthKey.p8"
step "Values: $ENV_FILE (both passwords, the signing identity, the key IDs)"
open "$WORK" 2>/dev/null || true
pause "Press Enter once all four are saved"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Store the secrets on GitHub"
say "Sets 8 repository secrets for the release workflow."
if confirm "Set them now (replacing any with the same names)?"; then
  set_secret APPLE_CERTIFICATE "$(base64 < "$WORK/developer-id.p12" | tr -d '\n')"
  set_secret APPLE_CERTIFICATE_PASSWORD "$APPLE_CERTIFICATE_PASSWORD"
  set_secret APPLE_SIGNING_IDENTITY "$APPLE_SIGNING_IDENTITY"
  set_secret APPLE_API_ISSUER "$APPLE_API_ISSUER"
  set_secret APPLE_API_KEY "$APPLE_API_KEY"
  set_secret APPLE_API_KEY_P8 "$(cat "$WORK/AuthKey.p8")"
  set_secret TAURI_SIGNING_PRIVATE_KEY "$(cat "$WORK/updater.key")"
  set_secret TAURI_SIGNING_PRIVATE_KEY_PASSWORD "$TAURI_SIGNING_PRIVATE_KEY_PASSWORD"
else
  SKIPPED+=("the 8 GitHub secrets: re-run this wizard")
fi

finish
note "Next: commit the public key in $CONF on a branch and merge it to main."
note "Then tag a release: docs/releasing.md."
note "Once everything is in your password manager, you can delete $WORK."
printf '\n'
}

run_wizard "$@"; exit
